import{_ as e,l as o,s as a,a as r,t as n,u as d,v as s,d as i,e as l,f as c,y as h,x as m,w as u,c as p,b,k as g,n as y,o as f,m as S,g as q,i as v,j as k,h as C,p as D,r as P,q as w}from"./chunks/node-get-json-keys.BH5whZCT.js";import{_,H as N,f as R,i as x}from"./chunks/framework.BIGTPeBz.js";const L=JSON.parse('{"title":"NS_DS_Commander","description":"","frontmatter":{},"headers":[],"relativePath":"en/plugins/ns-ds-commander.md","filePath":"en/plugins/ns-ds-commander.md"}'),I={name:"en/plugins/ns-ds-commander.md"};function T(M,t,O,G,A,E){return N(),R("div",null,[...t[0]||(t[0]=[x('<h1 id="ns-ds-commander" tabindex="-1">NS_DS_Commander <a class="header-anchor" href="#ns-ds-commander" aria-label="Permalink to &quot;NS_DS_Commander&quot;">​</a></h1><h2 id="plugin-introduction" tabindex="-1">Plugin Introduction <a class="header-anchor" href="#plugin-introduction" aria-label="Permalink to &quot;Plugin Introduction&quot;">​</a></h2><p>NS_DS_Commander is the client-side plugin of a complete <strong>UE5 Dedicated Server (DS) Scheduling &amp; Matchmaking System</strong>. It connects the UE side (player clients / DS game servers) to the Go-based server cluster, providing:</p><ul><li>Player matchmaking (grouped by map / region / team size / game mode)</li><li>Server (room) query, manual creation and shutdown</li><li>Player state synchronization (lobby / in game)</li><li>Lobby chat and room chat</li><li>DS registration, FPS reporting, custom field reporting, and joinable status control</li><li>Server-pushed notifications, kicks, shutdown countdown events, etc.</li></ul><p><strong>Module Information</strong></p><table class="ns-module-table"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module Name</td><td><code>NS_DS_Commander</code></td></tr><tr><td>Module Type</td><td>Runtime</td></tr><tr><td>Dependencies</td><td>Core, CoreUObject, Engine, WebSockets, Json, JsonUtilities</td></tr><tr><td>Engine Version</td><td>Unreal Engine 5.5</td></tr><tr><td>Core Class</td><td><code>UNS_MatchmakingSubsystem</code> (GameInstance subsystem, blueprint display name <code>NS_Matchmaking Subsystem</code>)</td></tr><tr><td>Utility Class</td><td><code>UNS_JsonUtilsBlueprintLibrary</code> (JSON utility library)</td></tr></tbody></table><h2 id="system-architecture" tabindex="-1">System Architecture <a class="header-anchor" href="#system-architecture" aria-label="Permalink to &quot;System Architecture&quot;">​</a></h2><p><img src="'+e+'" alt="System Architecture"></p><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><h3 id="player-client-integration-flow" tabindex="-1">Player Client Integration Flow <a class="header-anchor" href="#player-client-integration-flow" aria-label="Permalink to &quot;Player Client Integration Flow&quot;">​</a></h3><ol><li>Get the <strong>NS_Matchmaking Subsystem</strong> via <code>Get Subsystem</code> in the Game Instance blueprint</li><li>Call <strong>Connect To Server</strong> with the WebSocket address and password</li><li>Bind the required events (<code>On Connection Success</code>, <code>On Match Result</code>, etc. — see the node documentation below)</li><li>After <code>On Connection Success</code> fires, call <strong>Set Player Info</strong> to set the player name and player ID</li><li>Call <strong>Start Matchmaking</strong> to begin matching; in <code>On Match Result</code>, get the server address and enter via <code>Open Level</code> / <code>Client Travel</code></li></ol><p><img src="'+o+'" alt="Client Connection Flow"></p><h3 id="ds-server-integration-flow" tabindex="-1">DS Server Integration Flow <a class="header-anchor" href="#ds-server-integration-flow" aria-label="Permalink to &quot;DS Server Integration Flow&quot;">​</a></h3><ol><li>Get the <strong>NS_Matchmaking Subsystem</strong> in the DS GameMode blueprint</li><li>Call <strong>DS Connect To Child Server</strong>; the plugin automatically parses <code>-port=</code> from the command line and connects to the local child server</li><li>Call <strong>DS Set Room Joinable Status</strong> when needed to control whether new players can join</li><li>Call <strong>DS Report Custom Fields Data</strong> to report business custom fields (JSON string)</li><li>Bind <code>On DS Shutdown</code> to handle the scheduled shutdown countdown</li></ol><p><img src="'+a+'" alt="DS Connection Flow"></p><h2 id="get-subsystem" tabindex="-1">Get Subsystem <a class="header-anchor" href="#get-subsystem" aria-label="Permalink to &quot;Get Subsystem&quot;">​</a></h2><p>The subsystem is a <code>UGameInstanceSubsystem</code>, unique across the entire Game Instance lifecycle. The WebSocket connection is <strong>not disconnected when switching levels</strong>.</p><p>Get it in blueprint:</p><p><img src="'+r+'" alt="Get Subsystem"></p><h2 id="enums-structs" tabindex="-1">Enums &amp; Structs <a class="header-anchor" href="#enums-structs" aria-label="Permalink to &quot;Enums &amp; Structs&quot;">​</a></h2><h3 id="econnectionstatus" tabindex="-1">EConnectionStatus <a class="header-anchor" href="#econnectionstatus" aria-label="Permalink to &quot;EConnectionStatus&quot;">​</a></h3><p>Connection success / player info confirmation result status.</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td>Normal</td><td>Connected successfully</td></tr><tr><td>Banned</td><td>Account is banned (triggered when the server returns <code>banned=true</code>)</td></tr></tbody></table><hr><h3 id="eroomsourcetype" tabindex="-1">ERoomSourceType <a class="header-anchor" href="#eroomsourcetype" aria-label="Permalink to &quot;ERoomSourceType&quot;">​</a></h3><p>Room source type, used for <code>Get Room List</code> filtering and <code>Create Server</code> source.</p><table tabindex="0"><thead><tr><th>Value</th><th>Server <code>source_type</code></th><th>Description</th></tr></thead><tbody><tr><td>Match</td><td><code>match</code></td><td>Room automatically created by the matchmaking system</td></tr><tr><td>System</td><td><code>system</code></td><td>Room created by a system task</td></tr><tr><td>Activity</td><td><code>activity</code></td><td>Room created by an activity</td></tr></tbody></table><hr><h3 id="echattype" tabindex="-1">EChatType <a class="header-anchor" href="#echattype" aria-label="Permalink to &quot;EChatType&quot;">​</a></h3><p>Chat type, used by <code>Send Chat Message</code>.</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td>Lobby</td><td>Lobby chat, visible to all online players</td></tr><tr><td>Room</td><td>Room chat, only visible to players in the current room</td></tr></tbody></table><hr><h3 id="froominfo-room-info" tabindex="-1">FRoomInfo (Room Info) <a class="header-anchor" href="#froominfo-room-info" aria-label="Permalink to &quot;FRoomInfo (Room Info)&quot;">​</a></h3><p>Room information struct returned by the <code>Get Room List</code> callback (read-only).</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>RoomName</td><td>String</td><td>Room name</td></tr><tr><td>MapName</td><td>String</td><td>Map name</td></tr><tr><td>GameMode</td><td>String</td><td>Game mode</td></tr><tr><td>Region</td><td>String</td><td>Region</td></tr><tr><td>ServerIP</td><td>String</td><td>Server IP</td></tr><tr><td>Port</td><td>Integer</td><td>Server port</td></tr><tr><td>CurrentPlayers</td><td>Integer</td><td>Current player count</td></tr><tr><td>MaxPlayers</td><td>Integer</td><td>Maximum player count</td></tr><tr><td>TeamSize</td><td>Integer</td><td>Team size</td></tr><tr><td>bAllowJoin</td><td>Boolean</td><td>Whether new players can join</td></tr><tr><td>bAllowMatch</td><td>Boolean</td><td>Whether the room can be found by matchmaking (defaults to true if not provided by the server)</td></tr><tr><td>SourceType</td><td>String</td><td>Source type: <code>match</code> / <code>system</code> / <code>activity</code></td></tr><tr><td>PermissionTag</td><td>String</td><td>Permission tag (can be set for system / activity rooms)</td></tr><tr><td>FPS</td><td>Float</td><td>Current DS frame rate</td></tr></tbody></table><hr><h3 id="fcreateserverparams-create-server-params" tabindex="-1">FCreateServerParams (Create Server Params) <a class="header-anchor" href="#fcreateserverparams-create-server-params" aria-label="Permalink to &quot;FCreateServerParams (Create Server Params)&quot;">​</a></h3><p>Input parameters for <code>Create Server</code>. Fields match the &quot;Manual Create Server&quot; dialog in the Web admin panel.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Region</td><td>String</td><td>Empty</td><td>Region (corresponds to a key in the server&#39;s <code>create_server_config</code>, e.g. <code>Asia</code> / <code>NA</code> / <code>EU</code>)</td></tr><tr><td>RoomName</td><td>String</td><td>Empty</td><td>Room name; auto-generated if empty</td></tr><tr><td>MapName</td><td>String</td><td>Empty</td><td>Map name (required)</td></tr><tr><td>GameMode</td><td>String</td><td>Empty</td><td>Game mode (required)</td></tr><tr><td>TeamSize</td><td>Integer</td><td>1</td><td>Team size (must be ≥ 1)</td></tr><tr><td>bAllowMatch</td><td>Boolean</td><td>false</td><td>Whether the room can be found by matchmaking</td></tr><tr><td>bUseIdleTimeout</td><td>Boolean</td><td>false</td><td>Whether idle timeout auto-close is enabled (false = not affected by <code>room_idle_timeout</code>)</td></tr><tr><td>SourceType</td><td>ERoomSourceType</td><td>System</td><td>Source type; Match is reserved for the matchmaking system, the plugin defensively maps it to System</td></tr><tr><td>PermissionTag</td><td>String</td><td>Empty</td><td>Permission tag for business-side permission checks</td></tr><tr><td>EndAfterDays</td><td>Integer</td><td>0</td><td>End days (all three zero = no end time, no auto release)</td></tr><tr><td>EndAfterHours</td><td>Integer</td><td>0</td><td>End hours (≤ 23)</td></tr><tr><td>EndAfterMinutes</td><td>Integer</td><td>0</td><td>End minutes (≤ 59)</td></tr><tr><td>NotifyBeforeMinutes</td><td>Integer</td><td>0</td><td>Minutes before end to notify the DS</td></tr></tbody></table><hr><h3 id="fserverstats-server-stats" tabindex="-1">FServerStats (Server Stats) <a class="header-anchor" href="#fserverstats-server-stats" aria-label="Permalink to &quot;FServerStats (Server Stats)&quot;">​</a></h3><p>Statistics returned by the <code>Get Server Stats</code> callback (read-only).</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>LobbyPlayers</td><td>Integer</td><td>Players in lobby</td></tr><tr><td>MatchingPlayers</td><td>Integer</td><td>Players matchmaking</td></tr><tr><td>GamingPlayers</td><td>Integer</td><td>Players in game</td></tr><tr><td>TotalPlayers</td><td>Integer</td><td>Total online players</td></tr><tr><td>ServerCount</td><td>Integer</td><td>Number of child servers</td></tr><tr><td>RoomCount</td><td>Integer</td><td>Number of rooms</td></tr></tbody></table><h2 id="blueprint-nodes" tabindex="-1">Blueprint Nodes <a class="header-anchor" href="#blueprint-nodes" aria-label="Permalink to &quot;Blueprint Nodes&quot;">​</a></h2><p>Nodes are classified into three categories by available role. There is a <code>NetMode</code> check inside the code; calling with a mismatched role returns nothing:</p><ul><li><strong>【Client】</strong> Only callable by player clients; invalid on DS / listen servers</li><li><strong>【DS】</strong> Only callable by dedicated servers; invalid on clients</li><li><strong>【Common】</strong> Callable by both clients and DS</li></ul><hr><h3 id="player-side-functions" tabindex="-1">Player-Side Functions <a class="header-anchor" href="#player-side-functions" aria-label="Permalink to &quot;Player-Side Functions&quot;">​</a></h3><h4 id="connect-to-server【client】" tabindex="-1"><span style="color:#41aef5;">Connect To Server</span>【Client】 <a class="header-anchor" href="#connect-to-server【client】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Connect To Server&lt;/span&gt;【Client】&quot;">​</a></h4><p>Connects to the master (matchmaking) server. It first writes the input parameters into the subsystem&#39;s config properties, then initiates the WebSocket connection. On successful connection, it automatically sends the auth message (<code>client_type = player</code>).</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>InWebSocketURL</td><td>String</td><td>-</td><td>Master server WebSocket address, e.g. <code>ws://127.0.0.1:8088/ws</code></td></tr><tr><td>InPassword</td><td>String</td><td>-</td><td>Connection password (MD5 hashed inside the plugin before sending)</td></tr><tr><td>InReconnectAttempts</td><td>Integer</td><td>-1</td><td>Reconnect attempts; -1 = unlimited</td></tr><tr><td>InReconnectDelay</td><td>Float</td><td>5.0</td><td>Reconnect interval (seconds)</td></tr></tbody></table><p><strong>Notes</strong></p><ul><li>Calling on a DS / listen server returns immediately with a warning log</li><li>An empty URL returns immediately with an error log</li><li>On a wrong password, the server disconnects and the plugin does <strong>not</strong> auto-reconnect (no retry on auth failure)</li><li><code>On Connection Success</code> only fires after <code>Set Player Info</code> is called</li></ul><p><img src="'+n+'" alt="Node - ConnectToServer"></p><hr><h4 id="disconnect【client】" tabindex="-1"><span style="color:#41aef5;">Disconnect</span>【Client】 <a class="header-anchor" href="#disconnect【client】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Disconnect&lt;/span&gt;【Client】&quot;">​</a></h4><p>Disconnects the WebSocket and clears the reconnect timer.</p><p><img src="'+d+'" alt="Node - Disconnect"></p><hr><h4 id="is-connected【client】" tabindex="-1"><span style="color:#41aef5;">Is Connected</span>【Client】 <a class="header-anchor" href="#is-connected【client】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Is Connected&lt;/span&gt;【Client】&quot;">​</a></h4><p>Checks whether currently connected.</p><table tabindex="0"><thead><tr><th>Return</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>ReturnValue</td><td>Boolean</td><td>true when the WebSocket is connected <strong>and</strong> the player info has been confirmed by the server</td></tr></tbody></table><blockquote><p>After the DS connects to the child server, there is no player info confirmation step; it returns true as soon as the connection succeeds.</p></blockquote><p><img src="'+s+'" alt="Node - IsConnected"></p><hr><h4 id="start-matchmaking【client】" tabindex="-1"><span style="color:#41aef5;">Start Matchmaking</span>【Client】 <a class="header-anchor" href="#start-matchmaking【client】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Start Matchmaking&lt;/span&gt;【Client】&quot;">​</a></h4><p>Starts matchmaking.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>MapName</td><td>String</td><td>-</td><td>Map name</td></tr><tr><td>Region</td><td>String</td><td>-</td><td>Region, e.g. <code>Asia</code> / <code>NA</code> / <code>EU</code></td></tr><tr><td>TeamSize</td><td>Integer</td><td>1</td><td>Team size</td></tr><tr><td>GameMode</td><td>String</td><td>&quot;1&quot;</td><td>Game mode</td></tr></tbody></table><p><strong>Prerequisite</strong>: <code>Is Connected</code> is true, <code>Set Player Info</code> has been called, and not currently matchmaking.</p><p>Receive the result via <code>On Match Result</code>; error code <code>1</code> keeps the matchmaking state and keeps waiting.</p><p><img src="'+i+'" alt="Node - StartMatchmaking"></p><hr><h4 id="cancel-matchmaking【client】" tabindex="-1"><span style="color:#41aef5;">Cancel Matchmaking</span>【Client】 <a class="header-anchor" href="#cancel-matchmaking【client】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Cancel Matchmaking&lt;/span&gt;【Client】&quot;">​</a></h4><p>Cancels the current matchmaking. Requires being connected and currently matchmaking.</p><p><img src="'+l+'" alt="Node - CancelMatchmaking"></p><hr><h4 id="is-matchmaking【client】" tabindex="-1"><span style="color:#41aef5;">Is Matchmaking</span>【Client】 <a class="header-anchor" href="#is-matchmaking【client】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Is Matchmaking&lt;/span&gt;【Client】&quot;">​</a></h4><p>Checks whether currently matchmaking.</p><table tabindex="0"><thead><tr><th>Return</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>ReturnValue</td><td>Boolean</td><td>Whether matchmaking has been started and has not finished yet</td></tr></tbody></table><p><img src="'+c+'" alt="Node - IsMatchmaking"></p><hr><h4 id="set-player-info【client】" tabindex="-1"><span style="color:#41aef5;">Set Player Info</span>【Client】 <a class="header-anchor" href="#set-player-info【client】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Set Player Info&lt;/span&gt;【Client】&quot;">​</a></h4><p>Sets and submits the player info. <code>On Connection Success</code> only fires after the server confirms it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>InPlayerName</td><td>String</td><td>-</td><td>Player name (cannot be empty)</td></tr><tr><td>InPlayerID</td><td>String</td><td>-</td><td>Player unique ID (cannot be empty)</td></tr><tr><td>CustomData</td><td>String</td><td>Empty</td><td>Optional custom data, passed through to the server as-is</td></tr></tbody></table><p><strong>Notes</strong></p><ul><li>Must be called after the WebSocket is connected (it is normal for <code>Is Connected</code> to still be false at that point)</li><li>An empty player name or ID is skipped with a warning</li><li>After a successful reconnection, the plugin re-sends the player info automatically; no need to call again</li></ul><p><img src="'+h+'" alt="Node - SetPlayerInfo"></p><hr><h4 id="in-game【client】" tabindex="-1"><span style="color:#41aef5;">In Game</span>【Client】 <a class="header-anchor" href="#in-game【client】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;In Game&lt;/span&gt;【Client】&quot;">​</a></h4><p>Notifies the server that the player has entered the game (call after entering the DS map).</p><p><strong>Prerequisite</strong>: connected, player info set, and a current room ID exists (automatically recorded from <code>room_id</code> in <code>On Match Result</code>).</p><blockquote><p>After calling, the current room and state are saved, and on disconnect/reconnect the &quot;in game&quot; state is restored automatically.</p></blockquote><p><img src="'+m+'" alt="Node - InGame"></p><hr><h4 id="in-lobby【client】" tabindex="-1"><span style="color:#41aef5;">In Lobby</span>【Client】 <a class="header-anchor" href="#in-lobby【client】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;In Lobby&lt;/span&gt;【Client】&quot;">​</a></h4><p>Notifies the server that the player is back in the lobby (call when returning from the DS to the lobby).</p><p><strong>Note</strong>: if not connected when called, the plugin retries every 1 second until the connection is available, then sends automatically. The current room ID is cleared after calling.</p><p><img src="'+u+'" alt="Node - InLobby"></p><hr><h4 id="send-custom-operate-reply【client】" tabindex="-1"><span style="color:#41aef5;">Send Custom Operate Reply</span>【Client】 <a class="header-anchor" href="#send-custom-operate-reply【client】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Send Custom Operate Reply&lt;/span&gt;【Client】&quot;">​</a></h4><p>Replies with the result of a &quot;custom operation&quot; sent by the server. Must be called after receiving <code>On Message Notification</code> carrying a <code>request_id</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Result</td><td>String</td><td>Processing result string, business-defined</td></tr></tbody></table><p><strong>Note</strong>: returns immediately with an error log if there is no pending request ID; the request ID is cleared after a successful send.</p><p><img src="'+p+'" alt="Node - SendCustomOperateReply"></p><hr><h4 id="send-chat-message【client】" tabindex="-1"><span style="color:#41aef5;">Send Chat Message</span>【Client】 <a class="header-anchor" href="#send-chat-message【client】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Send Chat Message&lt;/span&gt;【Client】&quot;">​</a></h4><p>Sends a chat message.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>ChatType</td><td>EChatType</td><td>Lobby = lobby chat; Room = room chat</td></tr><tr><td>InPlayerName</td><td>String</td><td>Sender name (cannot be empty)</td></tr><tr><td>Content</td><td>String</td><td>Message content (cannot be empty)</td></tr></tbody></table><p><strong>Notes</strong></p><ul><li>There is a <strong>0.5 second</strong> send interval rate limit; calls that are too frequent are dropped with a warning</li><li>Room chat uses the current room ID recorded inside the plugin; sending without being in a room may be ineffective</li></ul><p><img src="'+b+'" alt="Node - SendChatMessage"></p><hr><h3 id="ds-side-functions" tabindex="-1">DS-Side Functions <a class="header-anchor" href="#ds-side-functions" aria-label="Permalink to &quot;DS-Side Functions&quot;">​</a></h3><h4 id="ds-connect-to-child-server【ds】" tabindex="-1"><span style="color:#f97316;">DS Connect To Child Server</span>【DS】 <a class="header-anchor" href="#ds-connect-to-child-server【ds】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#f97316&quot;&gt;DS Connect To Child Server&lt;/span&gt;【DS】&quot;">​</a></h4><p>Connects the DS to the local child server. The plugin automatically parses <code>-port=</code> from the startup command line (assigned and written into the launch arguments by the child server), connects to <code>ws://127.0.0.1:8081/ws</code> without authentication, then sends <code>ds_register</code> to register and starts <strong>FPS auto-reporting every 5 seconds</strong>.</p><p><strong>Notes</strong></p><ul><li>DS-only; invalid on clients</li><li>Returns immediately with an error log if <code>-port=</code> is missing from the command line</li><li>Connection timeout is 5 seconds; on failure, it reconnects up to 10 times at 5-second intervals</li><li>The parsed port is reused by <code>Set Room Joinable Status</code> / <code>Report Custom Fields Data</code> / <code>DS Close Room</code></li></ul><p><img src="'+g+'" alt="Node - DSConnectToChildServer"></p><hr><h4 id="ds-set-room-joinable-status【ds】" tabindex="-1"><span style="color:#f97316;">DS Set Room Joinable Status</span>【DS】 <a class="header-anchor" href="#ds-set-room-joinable-status【ds】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#f97316&quot;&gt;DS Set Room Joinable Status&lt;/span&gt;【DS】&quot;">​</a></h4><p>Sets whether the current room allows new players to join (e.g. closing the room after the match starts).</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>bAllowJoin</td><td>Boolean</td><td>true = allow joining; false = disallow</td></tr></tbody></table><p><strong>Prerequisite</strong>: connected to the child server and the port has been parsed successfully.</p><p><img src="'+y+'" alt="Node - DSSetRoomJoinableStatus"></p><hr><h4 id="ds-report-custom-fields-data【ds】" tabindex="-1"><span style="color:#f97316;">DS Report Custom Fields Data</span>【DS】 <a class="header-anchor" href="#ds-report-custom-fields-data【ds】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#f97316&quot;&gt;DS Report Custom Fields Data&lt;/span&gt;【DS】&quot;">​</a></h4><p>Reports business custom fields; the data is synced with the room info to the master server and the Web admin panel.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>JsonData</td><td>String</td><td>JSON string, e.g. <code>{&quot;level&quot;:5,&quot;mode&quot;:&quot;rank&quot;}</code></td></tr></tbody></table><p><strong>Note</strong>: if JSON parsing fails, it returns immediately with an error log; on success, the data is sent nested as a <code>custom_fields</code> object.</p><p><img src="'+f+'" alt="Node - DSReportCustomFieldsData"></p><hr><h4 id="ds-close-room【ds】" tabindex="-1"><span style="color:#f97316;">DS Close Room</span>【DS】 <a class="header-anchor" href="#ds-close-room【ds】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#f97316&quot;&gt;DS Close Room&lt;/span&gt;【DS】&quot;">​</a></h4><p>The DS actively requests to close the current room immediately (e.g. match ended, match error, or self-check failure).</p><p><strong>Note</strong>: only callable on a pure DS (<code>NM_DedicatedServer</code>); invalid on clients.</p><p><img src="'+S+'" alt="Node - DSCloseRoom"></p><hr><h3 id="common-functions" tabindex="-1">Common Functions <a class="header-anchor" href="#common-functions" aria-label="Permalink to &quot;Common Functions&quot;">​</a></h3><h4 id="get-available-regions【common】" tabindex="-1"><span style="color:#41aef5;">Get Available Regions</span>【Common】 <a class="header-anchor" href="#get-available-regions【common】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Get Available Regions&lt;/span&gt;【Common】&quot;">​</a></h4><p>Gets the available region list, returned via an asynchronous callback. The plugin requests the latest list from the master server in real time and returns the result through the callback when <code>available_regions_response</code> is received.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>OnComplete</td><td>Delegate</td><td><code>bSuccess</code>(Boolean) + <code>Regions</code>(String array)</td></tr></tbody></table><p><strong>Notes</strong></p><ul><li>If not connected, the callback fires immediately with <code>bSuccess = false</code> and an empty array, without making a network request</li><li>Callbacks are matched by <code>request_id</code> internally and can be called concurrently safely</li><li>After the connection is confirmed, the plugin automatically fetches the region list from the server once to update the cache (no callback); no need to call manually</li></ul><p><img src="'+q+'" alt="Node - GetAvailableRegions"></p><hr><h4 id="get-room-list【common】" tabindex="-1"><span style="color:#41aef5;">Get Room List</span>【Common】 <a class="header-anchor" href="#get-room-list【common】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Get Room List&lt;/span&gt;【Common】&quot;">​</a></h4><p>Gets the room list filtered by source type, returned via an asynchronous callback.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>SourceType</td><td>ERoomSourceType</td><td>Filter type: Match / System / Activity</td></tr><tr><td>OnComplete</td><td>Delegate</td><td><code>bSuccess</code>(Boolean) + <code>RoomList</code>(FRoomInfo array)</td></tr></tbody></table><p><strong>Notes</strong></p><ul><li>If not connected, the callback fires immediately with <code>bSuccess = false</code> and an empty array, without making a network request</li><li>Callbacks are matched by <code>request_id</code> internally and can be called concurrently safely</li><li>The server only returns rooms with an assigned port (DS already started), sorted by creation time in descending order</li></ul><p><img src="'+v+'" alt="Node - GetRoomList"></p><hr><h4 id="get-server-stats【common】" tabindex="-1"><span style="color:#41aef5;">Get Server Stats</span>【Common】 <a class="header-anchor" href="#get-server-stats【common】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Get Server Stats&lt;/span&gt;【Common】&quot;">​</a></h4><p>Gets the server cluster statistics, returned via an asynchronous callback.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>OnComplete</td><td>Delegate</td><td><code>bSuccess</code>(Boolean) + <code>Stats</code>(FServerStats)</td></tr></tbody></table><p>If not connected, the callback fires immediately with <code>bSuccess = false</code> and zero-value stats.</p><p><img src="'+k+'" alt="Node - GetServerStats"></p><hr><h4 id="create-server【common】" tabindex="-1"><span style="color:#41aef5;">Create Server</span>【Common】 <a class="header-anchor" href="#create-server【common】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Create Server&lt;/span&gt;【Common】&quot;">​</a></h4><p>Manually creates a server (room). Parameters match the &quot;Manual Create Server&quot; dialog in the Web admin panel; the result is returned via an asynchronous callback.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Params</td><td>FCreateServerParams</td><td>Create parameters (see the struct description)</td></tr><tr><td>OnComplete</td><td>Delegate</td><td><code>bSuccess</code>(Boolean) + <code>Message</code>(String) + <code>ErrorCode</code>(Integer)</td></tr></tbody></table><p><strong>Server validation rules</strong></p><ul><li><code>Region</code>, <code>MapName</code>, <code>GameMode</code> cannot be empty</li><li><code>TeamSize</code> must be ≥ 1</li><li><code>EndAfterHours</code> ≤ 23, <code>EndAfterMinutes</code> ≤ 59; end-time fields cannot be negative</li><li><code>NotifyBeforeMinutes</code> cannot be negative</li></ul><blockquote><p>A return of <code>bSuccess = true</code> means the <strong>create request has been accepted</strong> (the room waits for the cloud server to be created / the DS to start). You can then poll with <code>Get Room List</code> to check whether the room is ready.</p></blockquote><p><img src="'+C+'" alt="Node - CreateServer"></p><hr><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><p>All events are bindable multicast delegates. Bind them on the subsystem instance you obtained.</p><h3 id="on-connection-success" tabindex="-1"><span style="color:#bd0907;">On Connection Success</span> <a class="header-anchor" href="#on-connection-success" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Connection Success&lt;/span&gt;&quot;">​</a></h3><p>Triggered after the player info is confirmed by the server (only on the first confirmation; re-sent info after reconnection does not trigger it again).</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Status</td><td>EConnectionStatus</td><td>Normal = OK; Banned = account banned</td></tr></tbody></table><h3 id="on-connection-lost" tabindex="-1"><span style="color:#bd0907;">On Connection Lost</span> <a class="header-anchor" href="#on-connection-lost" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Connection Lost&lt;/span&gt;&quot;">​</a></h3><p>Triggered when the WebSocket connection is lost (connection error, closed by the server, etc.). After that, the plugin auto-reconnects according to <code>ReconnectAttempts</code> / <code>ReconnectDelay</code>.</p><h3 id="on-kicked-from-game" tabindex="-1"><span style="color:#bd0907;">On Kicked From Game</span> <a class="header-anchor" href="#on-kicked-from-game" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Kicked From Game&lt;/span&gt;&quot;">​</a></h3><p>Triggered when kicked by the server.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>KickDataJson</td><td>String</td><td>Full JSON string of the kick data; use the JSON utility functions to parse fields such as the reason</td></tr></tbody></table><h3 id="on-message-notification" tabindex="-1"><span style="color:#bd0907;">On Message Notification</span> <a class="header-anchor" href="#on-message-notification" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Message Notification&lt;/span&gt;&quot;">​</a></h3><p>Triggered when a server notification is received, including global notifications and &quot;custom operations&quot; (operation requests sent to a specific player from the Web admin panel).</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>EventName</td><td>String</td><td>Event name; empty for normal notifications</td></tr><tr><td>Content</td><td>String</td><td>Notification content</td></tr></tbody></table><blockquote><p>If the notification carries a <code>request_id</code> (custom operation), the plugin caches it; you can then reply via <strong>Send Custom Operate Reply</strong>.</p></blockquote><h3 id="on-match-result" tabindex="-1"><span style="color:#bd0907;">On Match Result</span> <a class="header-anchor" href="#on-match-result" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Match Result&lt;/span&gt;&quot;">​</a></h3><p>Matchmaking result callback.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>ServerAddress</td><td>String</td><td>Assigned DS address (IP:Port); empty on error</td></tr><tr><td>ErrorCode</td><td>Integer</td><td><code>0</code> = matched; <code>1</code> = no available server (still matchmaking); others = failure</td></tr></tbody></table><h3 id="on-lobby-chat-message" tabindex="-1"><span style="color:#bd0907;">On Lobby Chat Message</span> <a class="header-anchor" href="#on-lobby-chat-message" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Lobby Chat Message&lt;/span&gt;&quot;">​</a></h3><p>Triggered when a lobby chat message is received.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>SenderName</td><td>String</td><td>Sender name</td></tr><tr><td>Content</td><td>String</td><td>Message content</td></tr></tbody></table><h3 id="on-room-chat-message" tabindex="-1"><span style="color:#bd0907;">On Room Chat Message</span> <a class="header-anchor" href="#on-room-chat-message" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Room Chat Message&lt;/span&gt;&quot;">​</a></h3><p>Triggered when a room chat message is received.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>SenderName</td><td>String</td><td>Sender name</td></tr><tr><td>Content</td><td>String</td><td>Message content</td></tr></tbody></table><h3 id="on-ds-shutdown" tabindex="-1"><span style="color:#bd0907;">On DS Shutdown</span> <a class="header-anchor" href="#on-ds-shutdown" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On DS Shutdown&lt;/span&gt;&quot;">​</a></h3><p><strong>DS-specific event</strong>. Shutdown countdown notification broadcast by the server when a scheduled / manually created room is about to expire and close.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>RemainingSeconds</td><td>Integer</td><td>Seconds remaining before shutdown</td></tr></tbody></table><blockquote><p>Only the DS connected to a child server receives this event; player clients do not. Use it to show a &quot;Server will close in N seconds&quot; UI prompt and save results.</p></blockquote><h2 id="json-utility-functions" tabindex="-1">JSON Utility Functions <a class="header-anchor" href="#json-utility-functions" aria-label="Permalink to &quot;JSON Utility Functions&quot;">​</a></h2><p><code>UNS_JsonUtilsBlueprintLibrary</code> provides lightweight JSON read/write capabilities, commonly used to parse the JSON string from <code>On Kicked From Game</code>. All three functions are pure functions (no exec pins) and can be called in the editor.</p><h3 id="extract-json-value" tabindex="-1">Extract JSON Value <a class="header-anchor" href="#extract-json-value" aria-label="Permalink to &quot;Extract JSON Value&quot;">​</a></h3><p>Gets a value by key from a JSON string and converts it to a string.</p><table tabindex="0"><thead><tr><th>Parameter / Return</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>JsonString</td><td>String</td><td>JSON string to parse</td></tr><tr><td>Key</td><td>String</td><td>Key to get</td></tr><tr><td>ReturnValue</td><td>String</td><td>Strings returned as-is; integers formatted as <code>%.0f</code>, decimals as <code>%.2f</code>; booleans as <code>true</code> / <code>false</code>; empty string if not found</td></tr></tbody></table><p><img src="'+D+'" alt="Node - ExtractJsonValue"></p><hr><h3 id="json-has-key" tabindex="-1">JSON Has Key <a class="header-anchor" href="#json-has-key" aria-label="Permalink to &quot;JSON Has Key&quot;">​</a></h3><p>Checks whether a key exists in the JSON.</p><table tabindex="0"><thead><tr><th>Parameter / Return</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>JsonString</td><td>String</td><td>JSON string to parse</td></tr><tr><td>Key</td><td>String</td><td>Key to check</td></tr><tr><td>ReturnValue</td><td>Boolean</td><td>true if the key exists</td></tr></tbody></table><p><img src="'+P+'" alt="Node - JsonHasKey"></p><hr><h3 id="get-json-keys" tabindex="-1">Get JSON Keys <a class="header-anchor" href="#get-json-keys" aria-label="Permalink to &quot;Get JSON Keys&quot;">​</a></h3><p>Gets all keys of a JSON object.</p><table tabindex="0"><thead><tr><th>Parameter / Return</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>JsonString</td><td>String</td><td>JSON string to parse</td></tr><tr><td>ReturnValue</td><td>String array</td><td>List of all keys; empty array if parsing fails or the string is empty</td></tr></tbody></table><p><img src="'+w+'" alt="Node - GetJsonKeys"></p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ol><li><p><strong>Connection &amp; Authentication</strong></p><ul><li>The password is MD5 hashed (<code>FMD5::HashAnsiString</code>) before sending, and compared with the MD5 of the server-configured password</li><li>On auth failure the server actively disconnects and the plugin <strong>does not reconnect</strong>; check the password</li><li><code>Is Connected</code> means &quot;connected <strong>and</strong> player info confirmed&quot;, not whether the WebSocket is established</li></ul></li><li><p><strong>Reconnection</strong></p><ul><li>Auto-reconnects on connection error or close; interval controlled by <code>ReconnectDelay</code>, attempts by <code>ReconnectAttempts</code> (-1 = unlimited)</li><li>After reconnecting, the plugin re-sends the player info with the previous room ID and state to restore the &quot;in game&quot; state</li><li><code>On Connection Success</code> does <strong>not</strong> fire again after reconnection (only on the first confirmation)</li></ul></li><li><p><strong>Role Validation</strong></p><ul><li>Client-only nodes return nothing with a warning log when called on a DS / listen server</li><li>DS-only nodes return nothing when called on a client</li><li><code>DS Close Room</code> only works on a pure DS (<code>NM_DedicatedServer</code>)</li></ul></li><li><p><strong>DS Port &amp; Address</strong></p><ul><li>The DS port comes from the <code>-port=</code> command line argument, assigned by the child server; no manual entry needed</li><li>The DS connects to the child server at a fixed <code>ws://127.0.0.1:8081/ws</code> (local child server listening, no auth)</li></ul></li><li><p><strong>Async Callbacks</strong></p><ul><li><code>Get Room List</code> / <code>Get Server Stats</code> / <code>Create Server</code> match callbacks by <code>request_id</code> and can be called concurrently</li><li>Callbacks are not triggered on timeout; if the server does not respond, the callback is never called</li></ul></li><li><p><strong>Other</strong></p><ul><li>Chat messages are rate-limited to one send every 0.5 seconds</li><li>When the Game Instance is destroyed while the player is still in a room, the plugin automatically reports the <code>left_game</code> state</li><li><code>Get Available Regions</code> returns the region list pushed by the server in real time via callback and updates the local cache, keeping consistent with <code>available_regions</code> in <code>master_config.json</code></li><li>If the server does not provide the <code>allow_match</code> field, <code>FRoomInfo.bAllowMatch</code> stays <code>true</code></li></ul></li></ol>',211)])])}const B=_(I,[["render",T]]);export{L as __pageData,B as default};
